package ro.leo.visual;
import ro.leo.i18n.L;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.CalendarContract;import java.util.*;import java.util.concurrent.*;
/** One next alarm derived from CalendarProvider instances; no polling service. */
final class CalendarReminders {
 static final String FIRE="ro.leo.visual.CALENDAR_REMINDER";static final ExecutorService worker=Executors.newSingleThreadExecutor();
 static final class Next {long event,start,due;String title;String key(){return event+":"+start;}}
 static Uri instances(long from,long to){return CalendarContract.Instances.CONTENT_URI.buildUpon().appendPath(""+from).appendPath(""+to).build();}
 static long calendar(Context c){try(Cursor row=c.getContentResolver().query(CalendarContract.Calendars.CONTENT_URI,new String[]{"_id"},"account_name=? AND account_type=? AND name=?",new String[]{"Leo local",CalendarContract.ACCOUNT_TYPE_LOCAL,"Leo"},null)){return row!=null&&row.moveToFirst()?row.getLong(0):-1;}}
 static Next next(Context c,long now){long own=calendar(c);if(own<0)return null;HashMap<Long,Integer> minutes=new HashMap<Long,Integer>();try(Cursor r=c.getContentResolver().query(CalendarContract.Reminders.CONTENT_URI,new String[]{"event_id","minutes"},"minutes>=0 AND method=?",new String[]{""+CalendarContract.Reminders.METHOD_ALERT},null)){int count=0;while(r!=null&&r.moveToNext()&&count++<10000){long id=r.getLong(0);int m=r.getInt(1);Integer old=minutes.get(id);if(old==null||m>old)minutes.put(id,m);}}Next best=null;String last=c.getSharedPreferences("calendar-next",0).getString("last","");try(Cursor rows=c.getContentResolver().query(instances(now,now+366L*86400000),new String[]{"event_id","begin","title"},"calendar_id=?",new String[]{""+own},"begin ASC")){int count=0;while(rows!=null&&rows.moveToNext()&&count++<2000){Integer m=minutes.get(rows.getLong(0));if(m==null)continue;Next n=new Next();n.event=rows.getLong(0);n.start=rows.getLong(1);n.due=n.start-m*60000L;n.title=rows.getString(2);if(n.due>now&&!n.key().equals(last)&&(best==null||n.due<best.due))best=n;}}return best;}
 static PendingIntent pending(Context c){return PendingIntent.getBroadcast(c,6821,new Intent(c,CalendarReminderReceiver.class).setAction(FIRE),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(final Context c){HomeAgenda.invalidate();final Context app=c.getApplicationContext();worker.execute(new Runnable(){public void run(){try{scheduleNow(app);}catch(RuntimeException e){android.util.Log.w("LeoCalendar","Reminder schedule unavailable");}}});}
 static void scheduleNow(Context c){AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);a.cancel(pending(c));Next n=next(c,System.currentTimeMillis());android.content.SharedPreferences.Editor p=c.getSharedPreferences("calendar-next",0).edit();if(n==null){p.remove("event").remove("due").remove("start").remove("title").commit();return;}if(!p.putLong("event",n.event).putLong("start",n.start).putLong("due",n.due).putString("title",n.title==null?L.t("Eveniment Leo"):n.title).commit())return;a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,n.due,pending(c));}
 static void fire(Context c){android.content.SharedPreferences p=c.getSharedPreferences("calendar-next",0);long id=p.getLong("event",-1),start=p.getLong("start",0),due=p.getLong("due",0),now=System.currentTimeMillis();if(id<0||due>now+5000||now-due>3600000){scheduleNow(c);return;}String key=id+":"+start;if(key.equals(p.getString("last",""))){scheduleNow(c);return;}boolean exists=false;try(Cursor r=c.getContentResolver().query(CalendarContract.Events.CONTENT_URI,new String[]{"_id"},"_id=? AND calendar_id=? AND deleted=0 AND hasAlarm=1",new String[]{""+id,""+calendar(c)},null)){exists=r!=null&&r.moveToFirst();}if(exists&&p.edit().putString("last",key).commit()){NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("leo-calendar","Calendar Leo",NotificationManager.IMPORTANCE_DEFAULT));Intent open=new Intent(c,CalendarActivity.class).setData(Uri.parse("leo-calendar://event/"+id+"/"+start)).putExtra("day",start);PendingIntent click=PendingIntent.getActivity(c,6821,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AccessibilityPrefs.alert(c,"calendar");nm.notify("leo-calendar",key.hashCode(),new Notification.Builder(c,"leo-calendar").setSmallIcon(android.R.drawable.ic_menu_my_calendar).setContentTitle(p.getString("title",L.t("Eveniment Leo"))).setContentText(android.text.format.DateFormat.format("dd.MM HH:mm",start)).setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(click).setAutoCancel(true).build());}scheduleNow(c);}
}
